  .pom-count b { color: var(--accent); font-size: 13px; }
  .icon-btn { background: transparent; border: none; color: var(--muted); font-size: 16px; padding: 4px 6px; cursor: pointer; }
  .icon-btn:hover { color: var(--accent); }
  .icon-btn.del:hover { color: var(--danger); }
