<body>
<div class="app">
  <header>
    <div>
      <h1><span>Focus</span> Timer</h1>
      <div class="subtitle">A tiny, distraction-free pomodoro</div>
    </div>
    <div class="stats">
      <div>Sessions: <b id="statTotal">0</b></div>
      <div>Focus today: <b id="statToday">0m</b></div>
    </div>
  </header>

  <div class="modes">
    <button id="modeFocus" class="active" data-mode="focus">Focus</button>
    <button id="modeShort" data-mode="short">Short</button>
    <button id="modeLong" data-mode="long">Long</button>
  </div>

  <div class="ring-wrap">
    <div class="mode-label focus" id="modeLabel">Focus</div>
    <svg class="ring" width="220" height="220" viewBox="0 0 220 220">
      <circle class="ring-bg" cx="110" cy="110" r="100" fill="none" stroke-width="12"/>
      <circle class="ring-fg" id="ringFg" cx="110" cy="110" r="100" fill="none" stroke-width="12"
              stroke-dasharray="628.32" stroke-dashoffset="0"/>
    </svg>
  </div>

  <div class="time" id="timeDisplay" style="text-align:center">25:00</div>

  <div class="controls">
    <button class="primary" id="startBtn">Start</button>
    <button class="ghost" id="resetBtn">Reset</button>
    <button class="danger" id="skipBtn">Skip</button>
  </div>

  <hr>

  <div class="tasks-header">
    <h2>Tasks</h2>
  </div>
  <div class="add-row">
    <input id="taskInput" placeholder="What are you working on?" maxlength="120">
    <button id="addTaskBtn">Add</button>
  </div>
  <ul class="tasks" id="taskList"></ul>
  <div class="empty" id="emptyMsg">No tasks yet — add one above ☝️</div>

  <div class="hint">
    <kbd>Space</kbd> start/stop · <kbd>R</kbd> reset · <kbd>S</kbd> skip · <kbd>N</kbd> new task
  </div>
</div>

<div class="toast" id="toast"></div>

<script>
(function () {
  "use strict";

  var DEFAULT = { focus: 25*60, short: 5*60, long: 15*60 };
  var CIRC = 2 * Math.PI * 100; // 628.32

  var durations = Object.assign({}, DEFAULT);
  var mode = "focus";
  var running = false;
  var remaining = durations[mode];
  var totalSaved = 0;

  var el = {
    time: document.getElementById("timeDisplay"),
    ring: document.getElementById("ringFg"),
    modeLabel: document.getElementById("modeLabel"),
    start: document.getElementById("startBtn"),
    reset: document.getElementById("resetBtn"),
    skip: document.getElementById("skipBtn"),
    modeBtns: [].slice.call(document.querySelectorAll(".modes button")),
    taskInput: document.getElementById("taskInput"),
    addTask: document.getElementById("addTaskBtn"),
    taskList: document.getElementById("taskList"),
    empty: document.getElementById("emptyMsg"),
    statTotal: document.getElementById("statTotal"),
    statToday: document.getElementById("statToday"),
    toast: document.getElementById("toast"),
  };

  // ---- persistence ----
  function load(key, fallback) {
    try { var v = JSON.parse(localStorage.getItem(key)); return v == null ? fallback : v; } catch (e) { return fallback; }
  }
  function save(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {} }

  var state = load("focus.state", { totalSessions: 0, focusMinutes: 0, tasks: [], today: null });
  if (typeof state.totalSessions !== "number") state.totalSessions = 0;
  if (typeof state.focusMinutes !== "number") state.focusMinutes = 0;
  if (!Array.isArray(state.tasks)) state.tasks = [];
  persist();

  function persist() {
    state.today = todayKey();
    save("focus.state", state);
    renderStats();
  }

  function todayKey() {
    var d = new Date();
    return d.getFullYear() + "-" + (d.getMonth()+1) + "-" + d.getDate();
  }

  function renderStats() {
    el.statTotal.textContent = state.totalSessions;
    el.statToday.textContent = state.focusMinutes + "m";
  }

  function fmt(sec) {
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
  }

  function redraw() {
    el.time.textContent = fmt(remaining);
    var fraction = remaining / durations[mode];
    el.ring.setAttribute("stroke-dashoffset", String(CIRC * (1 - fraction)));
    el.modeLabel.textContent = mode.charAt(0).toUpperCase() + mode.slice(1);
    el.modeLabel.className = "mode-label " + mode;
    el.start.textContent = running ? "Pause" : "Start";
  }

  // ---- timer ----
  var tick = null;
  function start() {
    if (running) return;
    running = true;
    tick = setInterval(function () {
      remaining -= 1;
      if (remaining <= 0) { remaining = 0; redraw(); completeSession(); return; }
      redraw();
    }, 1000);
    redraw();
  }
  function pause() {
    running = false;
    if (tick) { clearInterval(tick); tick = null; }
    redraw();
  }
  function reset() {
    pause();
    remaining = durations[mode];
    redraw();
  }
  function skip() {
    pause();
    if (mode === "focus") nextMode("short");
    remaining = durations[mode];
    redraw();
  }

  function completeSession() {
    pause();
    state.totalSessions += 1;

    if (mode === "focus") {
      state.focusMinutes += Math.round(durations.focus / 60);
      // add a pomodoro to the active task if one exists
      var active = activeTask();
      if (active) { active.poms = (active.poms || 0) + 1; persist(); renderTasks(); }
      toast("Focus complete! 🎉 Time for a break.");
      nextMode("short");
    } else {
      toast(mode === "short" ? "Short break over — back to it!" : "Long break over — let'"'s go"'!");
      nextMode("focus");
    }
    remaining = durations[mode];
    persist();
    redraw();
  }

  function setMode(m) {
    if (m === mode) return;
    pause();
    mode = m;
    remaining = durations[mode];
    setActiveModeButton();
    redraw();
  }

  function nextMode(m) {
    mode = m;
    setActiveModeButton();
  }

  function setActiveModeButton() {
    el.modeBtns.forEach(function (b) { b.classList.toggle("active", b.dataset.mode === mode); });
  }

  // ---- tasks ----
  function activeTask() {
    for (var i = 0; i < state.tasks.length; i++) {
      if (!state.tasks[i].done) return state.tasks[i];
    }
    return null;
  }

  function addTask() {
    var txt = el.taskInput.value.trim();
    if (!txt) return;
    state.tasks.unshift({ id: Date.now(), text: txt, done: false, poms: 0 });
    el.taskInput.value = "";
    persist();
    renderTasks();
  }

  function toggleTask(id) {
    state.tasks.forEach(function (t) { if (t.id === id) t.done = !t.done; });
    persist();
    renderTasks();
  }

  function deleteTask(id) {
    state.tasks = state.tasks.filter(function (t) { return t.id !== id; });
    persist();
    renderTasks();
  }

  function renderTasks() {
    el.taskList.innerHTML = "";
    el.empty.style.display = state.tasks.length ? "none" : "block";
    state.tasks.forEach(function (t) {
      var li = document.createElement("li");
      if (t.done) li.className = "done";

      var check = document.createElement("div");
      check.className = "check";
      check.textContent = "✓";
      check.title = "toggle done";
      check.onclick = function () { toggleTask(t.id); };

      var text = document.createElement("div");
      text.className = "task-text";
      text.textContent = t.text;

      var poms = document.createElement("span");
      poms.className = "pom-count";
      poms.innerHTML = "<b>" + (t.poms || 0) + "</b> 🍅";

      var del = document.createElement("button");
      del.className = "icon-btn del";
      del.textContent = "✕";
      del.title = "delete";
      del.onclick = function () { deleteTask(t.id); };

      li.appendChild(check);
      li.appendChild(text);
      li.appendChild(poms);
      li.appendChild(del);
      el.taskList.appendChild(li);
    });
  }

  // ---- toast ----
  var toastTimer = null;
  function toast(msg) {
    el.toast.textContent = msg;
    el.toast.classList.add("show");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.toast.classList.remove("show"); }, 2600);
  }

  // ---- events ----
  el.start.onclick = function () { running ? pause() : start(); };
  el.reset.onclick = reset;
  el.skip.onclick = skip;
  el.modeBtns.forEach(function (b) { b.onclick = function () { setMode(b.dataset.mode); }; });
  el.addTask.onclick = addTask;
  el.taskInput.addEventListener("keydown", function (e) { if (e.key === "Enter") addTask(); });

  document.addEventListener("keydown", function (e) {
    if (e.target === el.taskInput) return;
    if (e.code === "Space") { e.preventDefault(); running ? pause() : start(); }
    else if (e.key === "r" || e.key === "R") reset();
    else if (e.key === "s" || e.key === "S") skip();
    else if (e.key === "n" || e.key === "N") { e.preventDefault(); el.taskInput.focus(); }
  });

  // ---- init ----
  if (state.today !== todayKey()) {
    // new day: keep sessions but reset today'"'s focus minutes
    state.focusMinutes = 0;
  }
  setActiveModeButton();
  renderTasks();
  redraw();
})();
</script>
</body>
</html>
